#!/usr/bin/env python3
# Some portions generated by Codex
import json,pathlib,statistics,sys
root=pathlib.Path(__file__).resolve().parent
groups={}
for name in sys.argv[1:]:
 result=json.loads((root/(name+'.json')).read_text());manifest=json.loads((root/(name+'-manifest.json')).read_text())
 if result['mode']!='measure' or not result.get('witnessesPassed'):raise SystemExit(f'{name}: not a verified timing trial')
 key=(manifest['variant'],manifest['writer'],result['size'])
 groups.setdefault(key,[]).append((name,result))
print('variant,writer,window,n,mean_full_ms,min_full_ms,max_full_ms,mean_first_record_ms,mean_window_ms,peak_server_rss_KiB')
for (variant,writer,size),runs in groups.items():
 vals=[r['endMs'] for _,r in runs]
 print(','.join(map(str,[variant,writer,size,len(vals),statistics.mean(vals),min(vals),max(vals),statistics.mean(r['firstRowMs'] for _,r in runs),statistics.mean(r['batchMs'] for _,r in runs),max(r['peakSampledServerRSSKiB'] for _,r in runs)])))
print('Full means terminal whole-query count, not all rows transferred. First record does not include DOM paint. These are fresh-server/first-query trials with ready overlay/adjacency and a copied fixture.')
